    {id=203,name="Follow Through",icon=155,cls=65535,cost=1,era=0,mr=16,desc="Each rank in this ability increases the chance of scoring an extra hit with all two-handed weapons that you wield."},
    {id=205,name="Slip Away",icon=155,cls=65535,cost=1,era=0,mr=5,desc="This ability grants you a chance to hide or evade while moving.  Each rank provides an increasing chance. You may train in this ability once each level after reaching level 61."},
    {id=210,name="Clever Working",icon=155,cls=65535,cost=1,era=0,mr=9,desc="Years of experimentation have led to the discovery of how to gain additional performance (in the form of critical spell hits) from weapons and other items. Each rank in this ability will increase your critical hit chance with such items."},
    {id=213,name="Read the Fight",icon=155,cls=65535,cost=1,era=0,mr=9,desc="Studying one's opponent for weaknesses provides the knowledge and ability to pierce through advanced defenses.  Each rank of this ability grants an increasing chance of bypassing an opponent's special defenses, such as dodge, block, parry, and riposte.  You may train in this ability at or after levels 61, 63, and 65."},
    {id=214,name="Stolen Vitality",icon=155,cls=65535,cost=1,era=0,mr=20,desc="This ability grants a chance that the healing effect on your lifetaps will provide an exceptional amount of healing.  Additional ranks further increase this effect."},
