    {id=222,name="Refuse to Fall",icon=155,cls=65535,cost=1,era=0,mr=3,desc="This ability grants a chance to endure what would otherwise be a stunning blow, from any angle, without being stunned.  You may train in the ranks of this ability at or after levels 61, 63, and 65."},
    {id=223,name="Ready Conjuring",icon=155,cls=65535,cost=1,era=0,mr=3,desc="This ability reduces the casting time of your summoning spells by 10, 25, and 50 percent."},
    {id=224,name="Wellspring",icon=155,cls=65535,cost=1,era=0,mr=29,desc="This ability increases your natural mana regeneration by 1 point per ability level."},
    {id=225,name="Slow Knitting",icon=155,cls=65535,cost=1,era=0,mr=31,desc="This ability raises your regeneration ability by 1 point per ability level up to rank 30, and 5 points per level for ranks 31 and up."},
    {id=309,name="Killing Edge",icon=155,cls=65535,cost=1,era=0,mr=6,desc="This ability increases your chance to land a critical hit.  Non-Warriors will nearly match the original critical hit abilities of Warriors, while Warriors will remain significantly ahead of other classes. further increases your chance to score a critical blow against your opponent."},
    {id=316,name="Tranquil Mind",icon=155,cls=65535,cost=1,era=0,mr=5,desc="Those who have meditated on the Plane of Tranquility find themselves able to expand their capacity of both Insight and Intellect.  Each rank of this ability raises the maximum that you may raise your Intelligence and Wisdom by ten points.  You may train in this ability once each level, beginning at level 61."},
    {id=367,name="Heavy Throw",icon=155,cls=65535,cost=1,era=0,mr=8,desc="Each rank of this ability increases the damage you do with throwing weapons."},
    {id=370,name="True Cast",icon=155,cls=65535,cost=1,era=0,mr=3,desc="This ability increases the accuracy of your thrown weapons."},
    {id=476,name="Tempered Frame",icon=155,cls=65535,cost=1,era=0,mr=1,desc="Your devotion to Norrath's Keepers grants you increased statistics."},
