    {id=479,name="Malefic Reach",icon=155,cls=65535,cost=1,era=0,mr=1,desc="Your devotion to Norrath's Keepers increases the chance that your direct damage spells, damage over time spells, healing spells, and melee attacks will have a critical effect."},
    {id=480,name="Warded Soul",icon=155,cls=65535,cost=1,era=0,mr=1,desc="Your devotion to Norrath's Keepers provides you with an innate chance to completely resist the effects of most detrimental spells."},
    {id=568,name="Sixth Sense",icon=155,cls=65535,cost=2,era=0,mr=1,desc="This ability grants you an innate chance to detect traps.  Any time you are near a trap, you will have a chance to detect it.  This chance is considerably lower than if you were actively searching for it."},
